604	/**
605	 * Writes one notification row per recipient, each with the channel set that
606	 * recipient's preferences allow. A recipient who has muted every channel is
607	 * skipped entirely rather than given a row nobody will ever see.
608	 */
609	export async function notify(
610	  orgId: OrgId,
611	  kind: NotificationKind,
612	  recipients: readonly UserId[],
613	  payload: NotificationPayload,
614	): Promise<readonly Notification[]> {
615	  if (recipients.length === 0) return [];
616	
617	  const org = await orgRepo.findOrgById(orgId);
618	  const flags: FlagContext = {
619	    orgId,
620	    userId: payload.actorId,
621	    plan: org?.plan ?? "free",
622	    role: null,
623	    overrides: org?.settings.enabledFlagOverrides,
624	  };
625	
626	  const rows = [];
627	
628	  for (const recipientId of new Set(recipients)) {
629	    if (recipientId === payload.actorId) continue;
630	
631	    const preference = await preferenceRepo.getPreference(
632	      orgId,
633	      recipientId,
634	      kind,
635	    );
636	    const channels = resolveChannels(preference, flags);
637	    if (channels.length === 0) continue;
638	
639	    rows.push({
640	      orgId,
641	      recipientId,
642	      kind,
643	      title: payload.title,
644	      body: payload.body,
645	      href: payload.href,
646	      actorId: payload.actorId,
647	      channels,
648	    });
649	  }
650	
651	  return notificationRepo.insertNotifications(orgId, rows);
652	}
