527	  const separatorAt = decoded.lastIndexOf(CURSOR_SEPARATOR);
528	  if (separatorAt <= 0 || separatorAt === decoded.length - 1) return null;
529	
530	  return {
531	    sortValue: decoded.slice(0, separatorAt),
532	    id: decoded.slice(separatorAt + 1),
