680	  "org:read": "viewer",
681	  "org:update": "admin",
682	  "org:delete": "owner",
683	  "org:manage_billing": "owner",
684	  "org:manage_flags": "admin",
685	  "member:read": "viewer",
686	  "member:invite": "admin",
687	  "member:update_role": "admin",
688	  "member:remove": "admin",
689	  "project:create": "member",
690	  "project:read": "viewer",
691	  "project:update": "member",
692	  "project:archive": "admin",
693	  "project:delete": "owner",
694	  "issue:create": "member",
695	  "issue:read": "viewer",
696	  "issue:update": "member",
697	  "issue:assign": "member",
698	  "issue:archive": "member",
699	  "issue:delete": "admin",
700	  "comment:create": "member",
701	  "comment:read": "viewer",
702	  "comment:update": "member",
703	  "comment:delete": "admin",
704	  "activity:read": "member",
705	  "activity:export": "admin",
