720	function isOwnedByActor(
721	  actor: Actor,
722	  resource: PermissionResource,
723	): boolean {
724	  switch (resource.kind) {
725	    case "issue":
726	      return (
727	        resource.authorId === actor.userId ||
728	        resource.assigneeId === actor.userId
729	      );
730	    case "comment":
731	      return resource.authorId === actor.userId;
732	    case "project":
733	      return resource.leadId === actor.userId;
734	    case "notification":
735	      return resource.recipientId === actor.userId;
736	    case "member":
