743	/**
744	 * Answers "may this actor perform this action on this resource?".
745	 *
746	 * @param actor    the authenticated principal, always scoped to one org
747	 * @param action   a member of the closed `PermissionAction` vocabulary
748	 * @param resource the object being acted on, discriminated on `kind`
749	 */
750	export function can(
751	  actor: Actor,
752	  action: PermissionAction,
753	  resource: PermissionResource,
754	): boolean {
755	  return explain(actor, action, resource).allowed;
756	}
