758	/** Same decision as `can()`, but reports why — used by the settings UI. */
759	export function explain(
760	  actor: Actor,
761	  action: PermissionAction,
762	  resource: PermissionResource,
763	): PermissionDecision {
764	  const base = { action, resourceKind: resource.kind } as const;
765	
766	  if (actor.orgId !== resource.orgId) {
767	    return { ...base, allowed: false, reason: "denied_cross_tenant" };
768	  }
769	
770	  if (actor.isPlatformStaff === true) {
771	    return { ...base, allowed: true, reason: "granted_by_staff" };
772	  }
773	
774	  const required = ROLE_MATRIX[action];
775	  if (required === undefined) {
776	    return { ...base, allowed: false, reason: "denied_unknown_action" };
777	  }
778	
779	  if (ROLE_RANK[actor.role] >= ROLE_RANK[required]) {
780	    return { ...base, allowed: true, reason: "granted_by_role" };
781	  }
782	
783	  if (OWNERSHIP_ESCALATIONS[action] === true && isOwnedByActor(actor, resource)) {
784	    return { ...base, allowed: true, reason: "granted_by_ownership" };
785	  }
786	
787	  return { ...base, allowed: false, reason: "denied_by_role" };
788	}
