861	    await issueRepo.findIssueById(input.orgId, input.issueId),
862	    "Issue",
863	    input.issueId,
864	  );
865	  assertCan(actor, "comment:create", issueResource(issue));
866	  assertNotArchived("Issue", issue.id, issue);
