979	/**
980	 * Union of the ids the client already resolved (optimistic UI) and the ones
981	 * parsed out of the body server-side. The server list wins on disagreement.
982	 */
983	async function resolveMentionedUsers(
984	  orgId: OrgId,
985	  body: string,
986	  clientProvided: readonly UserId[],
987	): Promise<readonly UserId[]> {
988	  const members = await memberRepo.listMembers({
989	    orgId,
990	    limit: MENTION_LOOKUP_LIMIT,
991	    cursor: null,
992	  });
993	
994	  const resolved = resolveMentions(body, members.items);
995	  const known = new Set(members.items.map((member) => member.userId));
996	
997	  return [
998	    ...new Set([...resolved, ...clientProvided.filter((id) => known.has(id))]),
999	  ];
