1615	/**
1616	 * Brings `databasePath` up to date. Generated migrations win when they exist;
1617	 * otherwise the embedded schema is pushed. Safe to run repeatedly — every
1618	 * statement is `IF NOT EXISTS`.
1619	 */
1620	export async function runMigrations(
1621	  databasePath: string = process.env.TASKFLOW_DB_PATH ?? DEFAULT_DB_PATH,
1622	): Promise<void> {
1623	  const absolute = resolve(process.cwd(), databasePath);
1624	  mkdirSync(dirname(absolute), { recursive: true });
1625	
1626	  const sqlite = new Database(absolute);
1627	  sqlite.pragma("journal_mode = WAL");
1628	
1629	  try {
1630	    for (const statement of readMigrationStatements()) {
1631	      sqlite.exec(statement);
1632	    }
1633	  } finally {
1634	    sqlite.close();
1635	  }
1636	}
1637	
1638	/** `pnpm db:migrate` runs this file directly; importing it must stay inert. */
1639	if (process.argv[1]?.endsWith("migrate.ts") === true) {
1640	  await runMigrations();
1641	}
1642	
1643	function readMigrationStatements(): readonly string[] {
1644	  const dir = resolve(process.cwd(), MIGRATIONS_DIR);
1645	  if (!existsSync(dir)) return SCHEMA_STATEMENTS;
1646	
1647	  const files = readdirSync(dir)
1648	    .filter((name) => name.endsWith(".sql"))
1649	    .sort();
1650	
1651	  if (files.length === 0) return SCHEMA_STATEMENTS;
1652	
1653	  return files.flatMap((name) =>
1654	    readFileSync(join(dir, name), "utf8")
1655	      .split("--> statement-breakpoint")
1656	      .map((chunk) => chunk.trim())
1657	      .filter(Boolean),
1658	  );
1659	}
