1687	export async function findMember(
1688	  orgId: OrgId,
1689	  userId: UserId,
1690	): Promise<Member | null> {
1691	  const row = getDb()
1692	    .select()
1693	    .from(members)
1694	    .where(
1695	      and(
1696	        orgPredicate(members.orgId, orgId),
1697	        eq(members.userId, userId),
1698	        liveMemberPredicate(),
1699	      ),
1700	    )
1701	    .get();
1702	  return row ? toMember(row) : null;
1703	}
