1717	/** Cursor-paged member list joined with the user record the UI renders. */
1718	export async function listMembers(
1719	  input: ListMembersInput,
1720	): Promise<Page<MemberWithUser>> {
1721	  const db = getDb();
1722	  const sort = { sortColumn: members.createdAt, idColumn: members.id };
1723	
1724	  const filters = compact(
1725	    orgPredicate(members.orgId, input.orgId),
1726	    liveMemberPredicate(),
1727	    input.role === undefined ? undefined : eq(members.role, input.role),
1728	    input.status === undefined ? undefined : eq(members.status, input.status),
1729	    input.query === undefined
1730	      ? undefined
1731	      : or(
1732	          like(users.name, `%${input.query}%`),
1733	          like(users.email, `%${input.query}%`),
1734	        ),
1735	  );
1736	
1737	  const total = db
1738	    .select({ value: count() })
1739	    .from(members)
1740	    .innerJoin(users, eq(users.id, members.userId))
1741	    .where(and(...filters))
1742	    .get();
1743	
1744	  const rows = db
1745	    .select({ member: members, user: users })
1746	    .from(members)
1747	    .innerJoin(users, eq(users.id, members.userId))
1748	    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
1749	    .orderBy(desc(members.createdAt), desc(members.id))
1750	    .limit(probeLimit(input.limit))
1751	    .all();
1752	
1753	  return toPage(
1754	    rows,
1755	    input.limit,
1756	    total?.value ?? 0,
1757	    (row) => ({ ...toMember(row.member), user: toUser(row.user) }),
1758	    (row) => ({ id: row.member.id, sortValue: row.member.createdAt }),
1759	  );
1760	}
