 * Marks a member out of office for `[startsAt, endsAt)`, optionally naming a
 * delegate. One absence per member: setting it again replaces the old one.
 */
export async function setAbsence(
  actor: Actor,
  input: SetAbsenceInput,
): Promise<MemberAbsence> {
  assertOrgScope(actor, input.orgId);
  assertMayManageAbsence(actor, input.orgId, input.userId);

  const delegateUserId = input.delegateUserId ?? null;
  const note = input.note ?? null;

  const starts = Date.parse(input.startsAt);
  const ends = Date.parse(input.endsAt);
  if (Number.isNaN(starts) || Number.isNaN(ends)) {
    throw new Error("An absence needs a valid start and end");
  }
  if (ends <= starts) {
    throw new Error("An absence must end after it starts");
  }
  if (note !== null && note.length > 200) {
    throw new Error("An absence note may be at most 200 characters");
  }

  await requireActiveMember(input.orgId, input.userId);

  if (delegateUserId !== null) {
    if (delegateUserId === input.userId) {
      throw new Error("A member cannot be their own delegate");
    }
    await requireActiveMember(input.orgId, delegateUserId);
  }

  return absenceRepo.upsertAbsence({
    orgId: input.orgId,
    userId: input.userId,
    delegateUserId,
    startsAt: input.startsAt,
    endsAt: input.endsAt,
    note,
  });
}

/** Clearing when nothing is set is a no-op. */
export async function clearAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  assertOrgScope(actor, orgId);
  assertMayManageAbsence(actor, orgId, userId);
  await requireActiveMember(orgId, userId);
  await absenceRepo.deleteAbsence(orgId, userId);
}

/**
 * The member's absence while it still matters: scheduled or running. Once the
 * end has passed it reads as `null`, exactly as if none was set.
 */
export async function getAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<MemberAbsence | null> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "member:read", orgResource(orgId));
  await requireActiveMember(orgId, userId);

  const absence = await absenceRepo.findAbsence(orgId, userId);
  if (absence === null) return null;
  return Date.parse(absence.endsAt) > Date.now() ? absence : null;
}

/** Your own absence is yours; anyone else's needs the role-change right. */
function assertMayManageAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): void {
  if (actor.userId === userId) return;
  assertCan(actor, "member:update_role", orgResource(orgId));
}

async function requireActiveMember(
  orgId: OrgId,
  userId: UserId,
): Promise<Member> {
  const member = await memberRepo.findMember(orgId, userId);
  if (!member || member.status !== "active" || member.archivedAt !== null) {
    throw new NotFoundError("Member", userId);
  }
  return member;
}

