/**
 * Out-of-office windows. One row per (org, user); every read is filtered by `orgId`.
 */
import { and, eq, isNull } from "drizzle-orm";
import { getDb, memberAbsences, members } from "@/server/db";
import { orgPredicate } from "./base-repository";
import { brandId, brandStamp } from "./_mappers";
import type { MemberAbsenceRow } from "@/server/db";
import type { OrgId, UserId } from "@/types/common";
import type { MemberAbsence } from "@/types/member";

function toAbsence(row: MemberAbsenceRow): MemberAbsence {
  return {
    orgId: brandId<OrgId>(row.orgId),
    userId: brandId<UserId>(row.userId),
    delegateUserId:
      row.delegateUserId === null ? null : brandId<UserId>(row.delegateUserId),
    startsAt: brandStamp(row.startsAt),
    endsAt: brandStamp(row.endsAt),
    note: row.note,
  };
}

export async function findAbsence(
  orgId: OrgId,
  userId: UserId,
): Promise<MemberAbsence | null> {
  const row = getDb()
    .select()
    .from(memberAbsences)
    .where(
      and(
        orgPredicate(memberAbsences.orgId, orgId),
        eq(memberAbsences.userId, userId),
      ),
    )
    .get();
  return row ? toAbsence(row) : null;
}

export async function upsertAbsence(
  absence: MemberAbsence,
): Promise<MemberAbsence> {
  const values = {
    delegateUserId: absence.delegateUserId,
    startsAt: absence.startsAt,
    endsAt: absence.endsAt,
    note: absence.note,
  };
  const row = getDb()
    .insert(memberAbsences)
    .values({ orgId: absence.orgId, userId: absence.userId, ...values })
    .onConflictDoUpdate({
      target: [memberAbsences.orgId, memberAbsences.userId],
      set: values,
    })
    .returning()
    .get();
  return toAbsence(row);
}

export async function deleteAbsence(
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  getDb()
    .delete(memberAbsences)
    .where(
      and(
        orgPredicate(memberAbsences.orgId, orgId),
        eq(memberAbsences.userId, userId),
      ),
    )
    .run();
}

/**
 * The stand-in for `userId` at instant `at`, or `null` when they are not away
 * (`startsAt <= at < endsAt`), named nobody, or the delegate is no longer an
 * active member. One hop only: the delegate's own absence is never consulted.
 */
export async function findActiveDelegate(
  orgId: OrgId,
  userId: UserId,
  at: Date,
): Promise<UserId | null> {
  const absence = await findAbsence(orgId, userId);
  if (absence === null || absence.delegateUserId === null) return null;

  const instant = at.getTime();
  if (
    !(Date.parse(absence.startsAt) <= instant) ||
    !(instant < Date.parse(absence.endsAt))
  ) {
    return null;
  }

  // The away member must still belong here, and so must the stand-in.
  for (const id of [userId, absence.delegateUserId]) {
    const live = getDb()
      .select({ id: members.id })
      .from(members)
      .where(
        and(
          orgPredicate(members.orgId, orgId),
          eq(members.userId, id),
          eq(members.status, "active"),
          isNull(members.archivedAt),
        ),
      )
      .get();
    if (!live) return null;
  }

  return absence.delegateUserId;
}
